#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    // If no argument is provided, the original program prints "BALANCED".
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *s = argv[1];
    size_t len = strlen(s);
    // The original binary uses a fixed‑size stack (max 0x1ff entries).
    // We mimic that with a modest static buffer.
    char stack[512];
    size_t sp = 0;          // stack pointer (number of items on stack)
    int balanced = 1;       // flag that becomes 0 on any mismatch

    for (size_t i = 0; i < len && balanced; ++i) {
        char c = s[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                if (sp < sizeof(stack)) {
                    stack[sp++] = c;
                } else {
                    // Stack overflow – treat as unbalanced.
                    balanced = 0;
                }
                break;
            case ')':
                if (sp == 0 || stack[sp-1] != '(') balanced = 0;
                else sp--;
                break;
            case ']':
                if (sp == 0 || stack[sp-1] != '[') balanced = 0;
                else sp--;
                break;
            case '}':
                if (sp == 0 || stack[sp-1] != '{') balanced = 0;
                else sp--;
                break;
            default:
                // The original program ignores any other characters.
                break;
        }
    }

    // After processing all characters the string is balanced only if
    // the stack is empty and no mismatch was detected.
    if (balanced && sp == 0) {
        puts("BALANCED");
    } else {
        puts("UNBALANCED");
    }
    return 0;
}
